import React, { useState } from 'react';
import './RecipeGenerator.css';

const DishResult = ({ recipes, servings }) => {
  const [selectedRecipe, setSelectedRecipe] = useState(null);

  const renderRecipeModal = () => {
    if (!selectedRecipe) return null;
    return (
      <div className="modal-overlay">
        <div className="modal-content card">
          <button className="modal-close-btn" onClick={() => setSelectedRecipe(null)}>✕</button>
          <div className="modal-body">
            <div className="recipe-header">
              <h2>{selectedRecipe.name}</h2>
              <div className="recipe-meta-tags">
                <span className="cuisine-tag">{selectedRecipe.cuisine}</span>
                <span className="time-tag">{selectedRecipe.cookTime}</span>
                <span className="servings-tag">{servings} servings</span>
              </div>
            </div>
            <div className="ingredients-section">
              <h3><span className="section-icon">📝</span>Ingredients</h3>
              <div className="ingredients-grid">
                {selectedRecipe.ingredients.map((ing, idx) => (
                  <div key={idx} className="ingredient-item">
                    <span className="ingredient-icon">🔸</span>
                    <span className="ingredient-name">{ing.ingredient}</span>
                    <span className="ingredient-amount">{ing.quantity} {ing.unit}</span>
                  </div>
                ))}
              </div>
            </div>
            <div className="instructions-section">
              <h3><span className="section-icon">👩‍🍳</span>Instructions</h3>
              <ol className="instructions-list">
                {selectedRecipe.instructions.map((step, idx) => (
                  <li key={idx} className="instruction-step">
                    <div className="step-number">{idx + 1}</div>
                    <div className="step-text">{step}</div>
                  </li>
                ))}
              </ol>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <section className="dish-result">
      <div className="container">
        <h1 className="page-title">🍽️ Dish Results</h1>
        <p className="page-subtitle">Here are your generated recipes:</p>
        <div className="recipes-grid">
          {recipes.map((recipe, index) => (
            <div key={index} className="recipe-card card">
              <div className="recipe-header">
                <h3>{recipe.name}</h3>
                <span className="recipe-cuisine">{recipe.cuisine}</span>
              </div>
              <div className="recipe-meta">
                <span className="meta-item">
                  <span className="meta-icon">⏱️</span>
                  {recipe.cookTime}
                </span>
                <span className="meta-item">
                  <span className="meta-icon">👥</span>
                  {servings} servings
                </span>
              </div>
              <div className="ingredients-section">
                <div className="matched-ingredients">
                  <h4><span className="section-icon">✅</span>Available Ingredients</h4>
                  <ul>
                    {recipe.matched.map((ing, i) => (
                      <li key={i}>{ing}</li>
                    ))}
                  </ul>
                </div>
                {recipe.missing.length > 0 && (
                  <div className="missing-ingredients">
                    <h4><span className="section-icon">❌</span>Missing Ingredients</h4>
                    <ul>
                      {recipe.missing.map((ing, i) => (
                        <li key={i}>{ing}</li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
              <div className="recipe-instructions">
                <h4><span className="section-icon">📝</span>Instructions</h4>
                <ol>
                  {recipe.instructions.map((step, i) => (
                    <li key={i}>{step}</li>
                  ))}
                </ol>
              </div>
              <button
                className="view-more-btn"
                onClick={() => setSelectedRecipe(recipe)}
              >
                View Details
              </button>
            </div>
          ))}
        </div>
        {renderRecipeModal()}
      </div>
    </section>
  );
};

export default DishResult;
